import type { TabsActivationDirection } from "@shardsui/svelte/tabs";
import { createChangeEventDetails, type ChangeEventDetails } from "$LIB$/change-event-details.js";

export type TabsChangeEventReason = "disabled" | "initial" | "missing" | "none";

export type TabsChangeEventDetails = ChangeEventDetails<
  TabsChangeEventReason,
  { readonly activationDirection: TabsActivationDirection }
>;

export function createTabsChangeEventDetails(
  reason: TabsChangeEventReason,
  activationDirection: TabsActivationDirection,
  event: Event | undefined,
  trigger: Element | undefined,
): TabsChangeEventDetails {
  return createChangeEventDetails(reason, event, trigger, { activationDirection });
}

export type TabsSize = "default" | "lg" | "sm";
export type TabsVariant = "default" | "underline";

export const tabsItemSizeClassNames: Record<TabsSize, string> = {
  default: "h-8.5 px-[calc(--spacing(2.5)-1px)] sm:h-7.5",
  lg: "h-9.5 px-[calc(--spacing(3)-1px)] sm:h-8.5",
  sm: "h-7.5 px-[calc(--spacing(2)-1px)] sm:h-6.5",
};

export const tabsItemLayoutClassName =
  "gap-1.5 [&_svg:not([class*='opacity-'])]:opacity-80 [&_svg:not([class*='size-'])]:size-4.5 sm:[&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:-mx-0.5 [&_svg]:shrink-0";

import { createContext } from "svelte";
import type { TabsActivationDirection } from "@shardsui/svelte/tabs";
import type { TabsSize, TabsVariant } from "./tabs-styles.js";
import type { TabsValue } from "./tabs-value.js";

export type TabsListStyleContext = {
  readonly size: TabsSize;
  readonly variant: TabsVariant;
};

export const [getTabsListStyleContext, setTabsListStyleContext] =
  createContext<TabsListStyleContext>();

export type TabsAdapterTab = {
  readonly disabled: boolean;
  readonly element: HTMLElement;
  readonly value: TabsValue;
};

export type TabsRootAdapterContext = {
  activationDirection(from: TabsValue | undefined, to: TabsValue): TabsActivationDirection;
  consumeEvent(): Event | undefined;
  currentTab(value: TabsValue | undefined): TabsAdapterTab | undefined;
  enabledTabs(): readonly TabsAdapterTab[];
  recordEvent(event: Event): void;
  registerTab(tab: TabsAdapterTab): () => void;
  readonly version: number;
};

export const [getTabsRootAdapterContext, setTabsRootAdapterContext] =
  createContext<TabsRootAdapterContext>();

export type { TabsActivationDirection, TabsOrientation } from "@shardsui/svelte/tabs";
export { Tabs as TabsPrimitive } from "@shardsui/svelte/tabs";
export type { TabsListStyleContext } from "./context.js";
export type {
  TabsChangeEventDetails,
  TabsChangeEventReason,
} from "./tabs-change-details.js";
export type { TabsIndicatorProps } from "./tabs-indicator.svelte";
export {
  default as Indicator,
  default as TabsIndicator,
} from "./tabs-indicator.svelte";
export type { TabsListProps } from "./tabs-list.svelte";
export {
  default as List,
  default as TabsList,
} from "./tabs-list.svelte";
export type { TabsPanelProps } from "./tabs-panel.svelte";
export {
  default as Content,
  default as Panel,
  default as TabsContent,
  default as TabsPanel,
} from "./tabs-panel.svelte";
export type { TabsRootProps } from "./tabs-root.svelte";
export {
  default as Root,
  default as Tabs,
  default as TabsRoot,
} from "./tabs-root.svelte";
export type { TabsSize, TabsVariant } from "./tabs-styles.js";
export { tabsItemLayoutClassName, tabsItemSizeClassNames } from "./tabs-styles.js";
export type { TabsTabProps } from "./tabs-tab.svelte";
export type { TabsValue } from "./tabs-value.js";
export {
  default as Tab,
  default as TabsTab,
  default as TabsTrigger,
  default as Trigger,
} from "./tabs-tab.svelte";
